<?php
declare(strict_types=1);require __DIR__.'/includes/bootstrap.php';require __DIR__.'/includes/document_manager.php';$token=(string)($_GET['t']??$_POST['t']??'');if($token===''){http_response_code(404);exit('Enlace inválido.');}$st=db()->prepare('SELECT s.*,d.title,v.original_name,v.stored_path,v.mime_type,v.file_size FROM document_shares s JOIN documents d ON d.id=s.document_id JOIN document_versions v ON v.id=s.version_id WHERE s.token_hash=? AND s.is_active=1 LIMIT 1');$st->execute([hash('sha256',$token)]);$s=$st->fetch();if(!$s||($s['expires_at']&&strtotime($s['expires_at'])<time())||($s['download_limit']!==null&&(int)$s['download_count']>=(int)$s['download_limit'])){http_response_code(410);exit('Este enlace ya no está disponible.');}if($s['password_hash']&&!($_SESSION['dms_public_ok_'.$s['id']]??false)){if($_SERVER['REQUEST_METHOD']==='POST'&&password_verify((string)($_POST['password']??''),$s['password_hash']))$_SESSION['dms_public_ok_'.$s['id']]=true;else{echo '<!doctype html><html><meta charset="utf-8"><meta name="viewport" content="width=device-width"><title>Documento protegido</title><body style="font-family:Arial;background:#eef4f8;padding:40px"><form method="post" style="max-width:420px;margin:auto;background:#fff;padding:28px;border-radius:16px"><h2>Documento protegido</h2><input type="hidden" name="t" value="'.e($token).'"><input type="password" name="password" placeholder="Contraseña" style="width:100%;box-sizing:border-box;padding:12px"><button style="margin-top:12px;padding:12px 18px;background:#0074c7;color:#fff;border:0;border-radius:8px">ABRIR</button></form></body></html>';exit;}}if(isset($_GET['download'])){if(!(int)$s['allow_download']){http_response_code(403);exit('Descarga deshabilitada.');}$path=dms_safe_path($s['stored_path']);if(!is_file($path)){http_response_code(404);exit('Archivo no disponible.');}db()->prepare('UPDATE document_shares SET download_count=download_count+1,last_accessed_at=NOW() WHERE id=?')->execute([(int)$s['id']]);dms_audit((int)$s['document_id'],'external_download','Enlace #'.$s['id'],null);header('Content-Type: application/octet-stream');header("Content-Disposition: attachment; filename*=UTF-8''".rawurlencode($s['original_name']));header('Content-Length: '.filesize($path));header('X-Content-Type-Options: nosniff');readfile($path);exit;}db()->prepare('UPDATE document_shares SET last_accessed_at=NOW() WHERE id=?')->execute([(int)$s['id']]);?><!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?=e($s['title'])?></title><style>body{font-family:Arial;background:#eef4f8;color:#163247;margin:0}.card{max-width:720px;margin:8vh auto;background:white;border-radius:18px;padding:32px;box-shadow:0 20px 50px #002f5720}.brand{color:#0074c7;font-weight:800}.btn{display:inline-block;padding:12px 18px;background:#0074c7;color:#fff;text-decoration:none;border-radius:9px;font-weight:700}</style></head><body><div class="card"><div class="brand">SÓCRATES CRM · DOCUMENT MANAGER</div><h1><?=e($s['title'])?></h1><p><?=e($s['original_name'])?> · <?=number_format((int)$s['file_size']/1024,1)?> KB</p><?php if((int)$s['allow_download']):?><a class="btn" href="?t=<?=e(urlencode($token))?>&download=1">DESCARGAR DOCUMENTO</a><?php else:?><p>El propietario habilitó este enlace solo para consulta de metadatos.</p><?php endif;?></div></body></html>